function sikapKelompok888(code,category){if(SIKAP_STANDAR_888[code])return {code,category:code.substring(3,4),service:SIKAP_STANDAR_888[code]};if(SIKAP_PETA_LAMA_888[code]){const c=SIKAP_PETA_LAMA_888[code];return {code:c,category:c.substring(3,4),service:SIKAP_STANDAR_888[c]};}if(SIKAP_PETA_FUNGSI_888[code]){const c=SIKAP_PETA_FUNGSI_888[code];return {code:'',category:c,service:FUNCTIONS9[c]};}const cat=FUNCTIONS9[category]?category:'H';return {code:'',category:cat,service:FUNCTIONS9[cat]};}
